fn map::(xs, fn) {
    let out = [];
    for x in xs { @push(out, fn(x)); }
    return out;
}

fn filter::(xs, fn) {
    let out = [];
    for x in xs {
        if (fn(x)) { @push(out, x); }
    }
    return out;
}

fn reduce::(xs, fn, init) {
    let acc = init;
    for x in xs { acc = fn(acc, x); }
    return acc;
}

fn sum::(xs) {
    let s = 0;
    for x in xs { s = s + x; }
    return s;
}

fn product::(xs) {
    let s = 1;
    for x in xs { s = s * x; }
    return s;
}

fn min_of::(xs) {
    if (@len(xs) == 0) { return null; }
    let m = xs[0];
    for x in xs { if (x < m) { m = x; } }
    return m;
}

fn max_of::(xs) {
    if (@len(xs) == 0) { return null; }
    let m = xs[0];
    for x in xs { if (x > m) { m = x; } }
    return m;
}

fn index_of::(xs, v) {
    let i = 0;
    while (i < @len(xs)) {
        if (xs[i] == v) { return i; }
        i = i + 1;
    }
    return -1;
}

fn contains::(xs, v) {
    return index_of(xs, v) >= 0;
}

fn unique::(xs) {
    let seen = {};
    let out = [];
    for x in xs {
        let k = @str(x);
        if (!@has(seen, k)) {
            seen[k] = 1;
            @push(out, x);
        }
    }
    return out;
}

fn flatten::(xs) {
    let out = [];
    for x in xs {
        if (@type(x) == "vec") {
            for y in x { @push(out, y); }
        } else {
            @push(out, x);
        }
    }
    return out;
}

fn chunks::(xs, size) {
    let out = [];
    let i = 0;
    while (i < @len(xs)) {
        let c = [];
        let j = 0;
        while (j < size && i + j < @len(xs)) {
            @push(c, xs[i + j]);
            j = j + 1;
        }
        @push(out, c);
        i = i + size;
    }
    return out;
}

fn take::(xs, n) {
    let out = [];
    let i = 0;
    while (i < n && i < @len(xs)) {
        @push(out, xs[i]);
        i = i + 1;
    }
    return out;
}

fn drop::(xs, n) {
    let out = [];
    let i = n;
    while (i < @len(xs)) {
        @push(out, xs[i]);
        i = i + 1;
    }
    return out;
}

fn zip::(a, b) {
    let out = [];
    let n = @len(a);
    if (@len(b) < n) { n = @len(b); }
    let i = 0;
    while (i < n) {
        @push(out, [a[i], b[i]]);
        i = i + 1;
    }
    return out;
}

fn range::(a, b) {
    let out = [];
    let i = a;
    while (i < b) {
        @push(out, i);
        i = i + 1;
    }
    return out;
}

fn repeat::(v, n) {
    let out = [];
    let i = 0;
    while (i < n) {
        @push(out, v);
        i = i + 1;
    }
    return out;
}

fn any::(xs, fn) {
    for x in xs {
        if (fn(x)) { return true; }
    }
    return false;
}

fn all::(xs, fn) {
    for x in xs {
        if (!fn(x)) { return false; }
    }
    return true;
}

fn count_if::(xs, fn) {
    let n = 0;
    for x in xs {
        if (fn(x)) { n = n + 1; }
    }
    return n;
}

fn find::(xs, fn) {
    for x in xs {
        if (fn(x)) { return x; }
    }
    return null;
}

fn group_by::(xs, fn) {
    let m = {};
    for x in xs {
        let k = @str(fn(x));
        if (!@has(m, k)) { m[k] = []; }
        @push(m[k], x);
    }
    return m;
}
